package main

import (
	"cmp"
	"errors"
	"io"
	"slices"
	"strings"
)

const readBufferSize = 1 << 16

// WordCount is a word together with its number of occurrences.
type WordCount struct {
	Word  string
	Count int
}

// Counter tallies occurrences of lowercase words.
type Counter struct {
	index map[string]int // word -> position in entries
	words []WordCount
}

// NewCounter returns an empty Counter.
func NewCounter() *Counter {
	return &Counter{index: make(map[string]int)}
}

// Add records one occurrence of word. The slice is not retained.
func (c *Counter) Add(word []byte) {
	// The string(word) conversion in a map index expression does not allocate.
	if i, ok := c.index[string(word)]; ok {
		c.words[i].Count++
		return
	}
	w := string(word)
	c.index[w] = len(c.words)
	c.words = append(c.words, WordCount{Word: w, Count: 1})
}

// Top returns up to limit words ordered by count descending, then word ascending.
func (c *Counter) Top(limit int) []WordCount {
	if limit <= 0 {
		return nil
	}
	best := make([]WordCount, 0, limit+1)
	for _, wc := range c.words {
		if len(best) == limit && compareRank(wc, best[len(best)-1]) >= 0 {
			continue
		}
		pos, _ := slices.BinarySearchFunc(best, wc, compareRank)
		best = slices.Insert(best, pos, wc)
		if len(best) > limit {
			best = best[:limit]
		}
	}
	return best
}

// compareRank orders by count descending, then by word in ascending byte order.
func compareRank(a, b WordCount) int {
	if c := cmp.Compare(b.Count, a.Count); c != 0 {
		return c
	}
	return strings.Compare(a.Word, b.Word)
}

// Count tokenizes r into maximal runs of ASCII letters, folds them to
// lowercase, and tallies them. Every other byte is a separator.
func Count(r io.Reader) (*Counter, error) {
	c := NewCounter()
	buf := make([]byte, readBufferSize)
	word := make([]byte, 0, 64)

	for {
		n, err := r.Read(buf)
		for _, b := range buf[:n] {
			if lower := b | 0x20; lower >= 'a' && lower <= 'z' {
				word = append(word, lower)
			} else if len(word) > 0 {
				c.Add(word)
				word = word[:0]
			}
		}
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, err
		}
	}
	if len(word) > 0 {
		c.Add(word)
	}
	return c, nil
}

package main

import (
	"slices"
	"strings"
	"testing"
)

func TestCountTop(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  []WordCount
	}{
		{"empty", "", nil},
		{"no words", "123 _' \xff\xc3(", nil},
		{"simple", "The cat and the hat.", []WordCount{{"the", 2}, {"and", 1}, {"cat", 1}, {"hat", 1}}},
		{"separators", "don't stop_me 4now, now-NOW", []WordCount{{"now", 3}, {"don", 1}, {"me", 1}, {"stop", 1}, {"t", 1}}},
		{"non-letters near letters", "a@b[c`d{e\xc1f\xe1g", []WordCount{{"a", 1}, {"b", 1}, {"c", 1}, {"d", 1}, {"e", 1}, {"f", 1}, {"g", 1}}},
		{"limit", "k j i h g f e d c b a a", []WordCount{{"a", 2}, {"b", 1}, {"c", 1}, {"d", 1}, {"e", 1}, {"f", 1}, {"g", 1}, {"h", 1}, {"i", 1}, {"j", 1}}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			c, err := Count(strings.NewReader(tt.input))
			if err != nil {
				t.Fatal(err)
			}
			if got := c.Top(topN); !slices.Equal(got, tt.want) {
				t.Errorf("Top = %v, want %v", got, tt.want)
			}
		})
	}
}

func TestWordSpanningReads(t *testing.T) {
	long := strings.Repeat("Ab", readBufferSize)
	c, err := Count(strings.NewReader(long + " " + long))
	if err != nil {
		t.Fatal(err)
	}
	got := c.Top(topN)
	if len(got) != 1 || got[0].Count != 2 || got[0].Word != strings.ToLower(long) {
		t.Errorf("unexpected result: %d entries", len(got))
	}
}

// Command wordfreq prints the ten most frequent ASCII words read from standard input.
package main

import (
	"bufio"
	"fmt"
	"os"
)

const topN = 10

func main() {
	counter, err := Count(os.Stdin)
	if err != nil {
		fmt.Fprintln(os.Stderr, "wordfreq:", err)
		os.Exit(1)
	}

	out := bufio.NewWriter(os.Stdout)
	for _, wc := range counter.Top(topN) {
		fmt.Fprintf(out, "%d %s\n", wc.Count, wc.Word)
	}
	if err := out.Flush(); err != nil {
		fmt.Fprintln(os.Stderr, "wordfreq:", err)
		os.Exit(1)
	}
}
